package demo.pharma.inventory;
import demo.pharma.common.web.PageResponse; import lombok.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/stock-movements") @RequiredArgsConstructor public class StockMovementController {private final StockMovementRepository movements;record View(UUID id,UUID batchId,String medicineName,String batchNumber,MovementType movementType,BigDecimal quantity,BigDecimal previousQuantity,BigDecimal newQuantity,String referenceType,UUID referenceId,String reason,Instant createdAt){}@GetMapping@PreAuthorize("hasAuthority('STOCK_VIEW')")PageResponse<View> list(@RequestParam(required=false)UUID batchId,@RequestParam(required=false)UUID medicineId,@RequestParam(required=false)MovementType type,@PageableDefault(size=30,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return PageResponse.of(movements.findAll((r,q,b)->{var x=b.conjunction();if(batchId!=null)x=b.and(x,b.equal(r.get("medicineBatch").get("id"),batchId));if(medicineId!=null)x=b.and(x,b.equal(r.get("medicineBatch").get("medicine").get("id"),medicineId));if(type!=null)x=b.and(x,b.equal(r.get("movementType"),type));return x;},p).map(this::v));}private View v(StockMovement m){return new View(m.getId(),m.getMedicineBatch().getId(),m.getMedicineBatch().getMedicine().getName(),m.getMedicineBatch().getBatchNumber(),m.getMovementType(),m.getQuantity(),m.getPreviousQuantity(),m.getNewQuantity(),m.getReferenceType(),m.getReferenceId(),m.getReason(),m.getCreatedAt());}}
